describe('Grim Halo mob skill',function()
 it('allows only its two-handed Fomor jobs and damages only after processing',function()
  local halo=require('scripts/actions/mobskills/grim_halo');local move,process=xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage;local params,damage=nil,nil;local job=xi.job.WAR;local mob={getMainJob=function()return job end,getWeaponDmg=function()return 77 end};local target={takeDamage=function(_,...)damage={...}end};for _,allowed in ipairs({xi.job.WAR,xi.job.BLM,xi.job.DRK,xi.job.SAM,xi.job.DRG,xi.job.SMN})do job=allowed;assert(halo.onMobSkillCheck(target,mob,{})==0)end;job=xi.job.MNK;assert(halo.onMobSkillCheck(target,mob,{})==1);xi.mobskills.mobPhysicalMove=function(_,_,_,_,v)params=v;return {damage=123,attackType=xi.attackType.PHYSICAL,damageType=xi.damageType.BLUNT}end;xi.mobskills.processDamage=function()return false end
  assert(halo.onMobWeaponSkill(mob,target,{},{})==123);assert(params.baseDamage==77 and params.numHits==1 and params.fTP[1]==2.5 and params.fTP[2]==2.5 and params.fTP[3]==2.5 and params.attackType==xi.attackType.PHYSICAL and params.damageType==xi.damageType.BLUNT and params.shadowBehavior==xi.mobskills.shadowBehavior.NUMSHADOWS_3 and params.canCrit and params.criticalChance[1]==.10 and params.criticalChance[2]==.20 and params.criticalChance[3]==.25 and damage==nil);xi.mobskills.processDamage=function()return true end;halo.onMobWeaponSkill(mob,target,{},{})
  xi.mobskills.mobPhysicalMove,xi.mobskills.processDamage=move,process;assert(damage[1]==123 and damage[2]==mob and damage[3]==xi.attackType.PHYSICAL and damage[4]==xi.damageType.BLUNT)
 end)
end)
